import React, { useState, FormEvent } from 'react';
import {
  JxForm,
  JxFormField,
  JxLabel,
  JxInput,
  JxSelect,
  JxSelectOption,
  JxSwitch,
  JxButton,
  JxStack,
} from '@jinx-ui/react';

export interface ProfileSettings {
  name: string;
  language: 'ru' | 'en';
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  onSave: (settings: ProfileSettings) => void;
  initialSettings?: ProfileSettings;
}

const DEFAULT_SETTINGS: ProfileSettings = {
  name: '',
  language: 'ru',
  emailNotifications: true,
};

const ProfileSettingsForm: React.FC<ProfileSettingsFormProps> = ({
  onSave,
  initialSettings = DEFAULT_SETTINGS,
}) => {
  const [name, setName] = useState(initialSettings.name);
  const [language, setLanguage] = useState<'ru' | 'en'>(initialSettings.language);
  const [emailNotifications, setEmailNotifications] = useState(
    initialSettings.emailNotifications
  );

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name, language, emailNotifications });
  };

  return (
    <JxForm onSubmit={handleSubmit} className="jx-p-4">
      <JxStack direction="column" gap="var(--jx-space-4)">
        <JxFormField>
          <JxLabel htmlFor="profile-name">Имя</JxLabel>
          <JxInput
            id="profile-name"
            name="name"
            value={name}
            placeholder="Введите ваше имя"
            onChange={(event: React.ChangeEvent<HTMLInputElement>) =>
              setName(event.target.value)
            }
          />
        </JxFormField>

        <JxFormField>
          <JxLabel htmlFor="profile-language">Язык интерфейса</JxLabel>
          <JxSelect
            id="profile-language"
            name="language"
            value={language}
            onChange={(value: string) => setLanguage(value as 'ru' | 'en')}
          >
            <JxSelectOption value="ru">Русский</JxSelectOption>
            <JxSelectOption value="en">Английский</JxSelectOption>
          </JxSelect>
        </JxFormField>

        <JxFormField>
          <JxStack direction="row" align="center" justify="space-between">
            <JxLabel htmlFor="profile-email-notifications">
              Уведомления на почту
            </JxLabel>
            <JxSwitch
              id="profile-email-notifications"
              name="emailNotifications"
              checked={emailNotifications}
              onChange={(checked: boolean) => setEmailNotifications(checked)}
            />
          </JxStack>
        </JxFormField>

        <JxButton type="submit" variant="primary">
          Сохранить
        </JxButton>
      </JxStack>
    </JxForm>
  );
};

export default ProfileSettingsForm;

